SELECT DISTINCT cs_substr.canonical_smiles, cr_substr.compound_name AS substrate_compound_name, md_parent.pref_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m INNER JOIN compound_records cr_substr ON m.substrate_record_id = cr_substr.record_id INNER JOIN molecule_dictionary md_substr ON cr_substr.molregno = md_substr.molregno INNER JOIN compound_structures cs_substr ON md_substr.molregno = cs_substr.molregno INNER JOIN compound_records cr_parent ON m.drug_record_id = cr_parent.record_id INNER JOIN molecule_dictionary md_parent ON cr_parent.molregno = md_parent.molregno WHERE m.organism = 'Canis lupus familiaris' ORDER BY cs_substr.canonical_smiles ASC, cr_substr.compound_name ASC, md_parent.pref_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200
